CREATE OR REPLACE FUNCTION public.morth_pricing_snapshot(p_year text, p_zone text, p_requests jsonb, p_resource_codes text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare quotes jsonb;resources jsonb;
begin
 if p_year not in ('2026-27','2025-26') or p_year is null then
  raise exception using errcode='22023',message='Select 2026-27 or 2025-26';
 end if;
 if p_zone not in ('zone_1','zone_2','zone_3') or p_zone is null then
  raise exception using errcode='22023',message='Select a valid labour zone';
 end if;
 if jsonb_typeof(p_requests) is distinct from 'array' then
  raise exception using errcode='22023',message='Quote requests must be a JSON array';
 end if;
 if jsonb_array_length(p_requests)>256 or coalesce(cardinality(p_resource_codes),0)>1000 then
  raise exception using errcode='22023',message='Too many pricing identities in one request';
 end if;
 if exists(select 1 from jsonb_array_elements(p_requests) x
   where jsonb_typeof(x) is distinct from 'object' or coalesce(x->>'recipe_code','')=''
   or coalesce(x->>'component','rate') not in
     ('rate','total','hire_total','hire_charge','fuel_charge','crew_charge','capital_cost','tyres_tubes_cost')) then
  raise exception using errcode='22023',message='Invalid quote recipe or rate component';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'recipe_code',x->>'recipe_code',
   'component',coalesce(x->>'component','rate'),
   'quote',public.sor_resource_quote(x->>'recipe_code',p_year,p_zone,coalesce(x->>'component','rate'),null)
 ) order by n),'[]'::jsonb) into quotes
 from jsonb_array_elements(p_requests) with ordinality q(x,n);
 select coalesce(jsonb_agg(jsonb_build_object(
   'resource_code',a.resource_code,'unit',a.unit,'status',a.status,
   'pricing_records',a.pricing_records
 ) order by a.resource_code),'[]'::jsonb) into resources
 from public.analysis_resource a where a.resource_code=any(coalesce(p_resource_codes,'{}'::text[]));
 return jsonb_build_object('year',p_year,'zone',p_zone,'fetched_at',statement_timestamp(),
   'quotes',quotes,'resources',resources);
end;
$function$

CREATE OR REPLACE FUNCTION public.sor_morth_analysis_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare o jsonb;
begin
 if tg_op='UPDATE' and old.rate->>'type'='morth_analysis' and new.rate->>'type' is distinct from 'morth_analysis' then
  raise exception 'Do not discard reviewed MoRTH Rate links during re-extraction; replay the exact-year reviewed manifest';
 end if;
 if new.rate->>'type' is distinct from 'morth_analysis' then return new; end if;
 if not public.sor_morth_analysis_rate_valid(new.rate) then raise exception 'Invalid MoRTH analysis reference'; end if;
 if new.part_no<>2 or new.table_code<>'P02-T03' or new.metadata->'cost_ready' is distinct from 'false'::jsonb
  or new.metadata->'cost_review'->>'status' is distinct from 'analysis_required'
  or new.metadata->'morth_link_review'->'reviewer'->>'kind' is distinct from 'ai'
  or coalesce(new.metadata->'morth_link_review'->'reviewer'->>'model','')=''
  then raise exception 'MoRTH research candidates must retain explicit AI evidence and costing hold'; end if;
 for o in select value from jsonb_array_elements(new.rate->'options') loop
  if not exists(select 1 from public.morth m where m.code=o->>'morth_code'
    and m.source_edition=o->>'source_edition' and m.source_pages=o->'source_pages') then
   raise exception 'Unknown or changed MoRTH key/source evidence: %',o->>'morth_code';
  end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.sor_morth_analysis_options(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare resolved jsonb; y public."SOR_Year"; n bigint; options jsonb;
begin
 resolved:=public.sor_resolve_recipe_year(p_recipe_code,p_year);
 if coalesce((resolved->>'requires_review')::boolean,false) then return resolved; end if;
 select count(*) into n from public."SOR_Year" where recipe_code=resolved->>'recipe_code' and year=p_year;
 if n<>1 then return resolved||jsonb_build_object('status',case when n=0 then 'selected_year_rate_missing' else 'annual_scope_review_required' end,'rate',null); end if;
 select * into y from public."SOR_Year" where recipe_code=resolved->>'recipe_code' and year=p_year;
 if y.rate->>'type' is distinct from 'morth_analysis' then return resolved||jsonb_build_object('status','not_morth_analysis_reference','rate',null); end if;
 select coalesce(jsonb_agg(o.value||jsonb_build_object('description',m.description,
  'description_detail',m.description_detail,'project_category',m.project_category,'unit',m.unit,
  'analysis_quantity',m.analysis_quantity,'rate_divisor',m.rate_divisor,'analysis',m.recipe,
  'can_auto_price',false) order by o.n),'[]'::jsonb) into options
 from jsonb_array_elements(y.rate->'options') with ordinality o(value,n)
 join public.morth m on m.code=o.value->>'morth_code';
 return resolved||jsonb_build_object('year',p_year,'year_row_code',y.year_row_code,'unit',y.unit,'status',y.rate->>'status',
  'rate',null,'cost_ready',false,'options',options,'requirements',y.rate->'requirements','reason',y.rate->>'reason',
  'review',y.metadata->'morth_link_review','to_be_printed',y.to_be_printed);
end $function$
